ValidationRule.errorConditionFormula:
IF(AND( EYI_Opportunity__r.EYI_Inventory__r.EYI_RERA_Applicable__c = false, EYI_Opportunity__r.EYI_Booking_Amount_Received__c <= ( EYI_Opportunity__r.SyncedQuote.EYI_Agreement_Value__c * 0.96),
OR(
TEXT(EYI_Opportunity__r.StageName) = "Block",
TEXT(EYI_Opportunity__r.StageName) = "Booking"
)
) , true, false)
